 UPPER(OM.SKU_GROUP) LIKE \'4BSW%\' OR UPPER(OM.SKU_GROUP) LIKE \'4BHD%\' OR UPPER(OM.SKU_GROUP) LIKE \'4BOS%\' OR UPPER(OM.SKU_GROUP) LIKE \'4BSH%\' OR UPPER(OM.SKU_GROUP) LIKE \'4BBL%\' OR UPPER(OM.SKU_GROUP) LIKE \'4BCA%\' OR UPPER(OM.SKU_GROUP) LIKE \'4BCD%\' OR UPPER(OM.SKU_GROUP) LIKE \'4BJO%\' THEN \'PLUS\' ELSE \'SNITCH\' END ) AS STYLE, MAX( CASE WHEN UPPER(OM.CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN TRIM(LOWER(OM.COLLAR_NEW)) IN (\'polo\',\'cuban\',\'baseball\',\'mandarin\',\'mock\',\'high neck\',\'zip\',\'spread\') THEN \'POLO\' ELSE \'ROUND\' END WHEN UPPER(OM.CATEGORY) = \'SHIRTS\' THEN CASE WHEN LOWER(OM.STYLE) LIKE \'%linen%\' OR UPPER(OM.MATERIAL_NEW) = \'LINEN\' THEN \'LINEN\' WHEN UPPER(OM.MATERIAL_NEW) = \'COTTON\' THEN \'COTTON\' ELSE \'POLYESTER\' END WHEN UPPER(OM.CATEGORY) IN (\'TROUSERS\', \'CHINOS\') THEN CASE WHEN UPPER(OM.FIT) IN (\'BAGGY FIT\', \'BELLBOTTOM FIT\') THEN \'BAGGY FIT\' WHEN UPPER(OM.FIT) IN (\'CARROT FIT\', \'BALLOON FIT\') THEN \'CARROT FIT\' WHEN UPPER(OM.FIT) IN (\'CUSTOM FIT\', \'CUSTOM REGULAR FIT\', \'CUSTOM STRAIGHT FIT\') THEN \'CUSTOM FIT\' WHEN UPPER(OM.FIT) IN (\'LOOSE FIT\', \'WIDE FIT\', \'WIDE LEG\') THEN \'LOOSE FIT\' WHEN UPPER(OM.FIT) = \'SLIM FIT\' THEN \'SLIM FIT\' WHEN UPPER(OM.FIT) IN (\'COMFORT FIT\', \'REGULAR FIT\', \'RELAXED FIT\', \'STRAIGHT FIT\') THEN \'STRAIGHT FIT\' ELSE \'STRAIGHT FIT\' END WHEN UPPER(OM.CATEGORY) = \'JEANS\' THEN CASE WHEN UPPER(OM.FIT) IN (\'TAPERED FIT\',\'REGULAR FIT\',\'RELAXED FIT\',\'STRAIGHT FIT\',\'COMFORT FIT\',\'LOOSE FIT\',\'STRAIGHT LOOSE FIT\') THEN \'STRAIGHT FIT\' WHEN UPPER(OM.FIT) IN (\'SUPER BAGGY FIT\',\'SLOUCHY FIT\',\'BAGGY FIT\') THEN \'BAGGY FIT\' WHEN UPPER(OM.FIT) IN (\'BOOTCUT\',\'FLARED FIT\') THEN \'BOOTCUT\' WHEN UPPER(OM.FIT) IN (\'CARROT FIT\',\'BALLOON FIT\') THEN \'CARROT FIT\' WHEN UPPER(OM.FIT) = \'SLIM FIT\' THEN \'SLIM FIT\' WHEN UPPER(OM.FIT) = \'SKINNY FIT\' THEN \'SKINNY FIT\' ELSE \'STRAIGHT FIT\' END END ) AS META1, MAX( CASE WHEN UPPER(OM.CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN UPPER(TRIM(OM.STYLE)) LIKE \'%TECHNICAL%\' OR UPPER(TRIM(OM.STYLE)) LIKE \'%STITCHLESS%\' THEN \'TECHNICAL\' WHEN UPPER(TRIM(OM.DESIGNS)) = \'SOLID\' THEN \'CORE\' ELSE \'FASHION\' END WHEN UPPER(OM.CATEGORY) = \'SHIRTS\' THEN CASE WHEN UPPER(TRIM(OM.STYLE)) LIKE \'%TECHNICAL%\' OR UPPER(TRIM(OM.STYLE)) LIKE \'%STITCHLESS%\' THEN \'TECHNICAL\' WHEN UPPER(TRIM(OM.DESIGNS)) = \'SOLID\' THEN \'SOLID\' WHEN UPPER(TRIM(OM.DESIGNS)) = \'STRIPES\' THEN \'STRIPES\' WHEN UPPER(TRIM(OM.DESIGNS)) IN (\'TEXTURED\',\'SELF DESIGN\') THEN \'SELF DESIGN & TEXTURED\' WHEN UPPER(TRIM(OM.DESIGNS)) = \'CHECKS\' THEN \'CHECKS\' WHEN UPPER(TRIM(OM.DESIGNS)) IN (\'EMBROIDED\',\'EMBELLISHED\') THEN \'EMBROIDED\' ELSE \'PRINTED\' END END ) AS META2, MAX( CASE WHEN UPPER(OM.CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN UPPER(TRIM(OM.FIT)) IN (\'OVERSIZED\',\'BOX FIT\',\'RELAXED FIT\') THEN \'OVERSIZED FIT\' WHEN UPPER(TRIM(OM.FIT)) = \'SLIM FIT\' THEN \'SLIM FIT\' ELSE \'REGULAR FIT\' END END ) AS META3 FROM SNITCH_DB.MAPLEMONK.METAFIELDS_DATA OM GROUP BY OM.SKU_GROUP;",
